// CONSTRUCTORS =It is a special member function with same name as that of class
//              =It is used to initialize the objects of the class
//              =It is automatically invoked(called) whenever an object is made
/** PROPERTIES
 * constructor which does not accept any parameters === default constructor
 * it should be declared in the public section of the class
 * They are automatically invoked(called) whenever object is created
 * They cannot  return values and do not have return type
 * It can have default arguments....................
 * We cannot refer to their address
 */

#include <iostream>
using namespace std;
class complex
{
    int a, b;

public:
    complex(void); // constructor declaration //DEFAULT CONSTRUCTOR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    void printData()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
    {
        cout << "The complex number is" << a << "+" << b << "i" << endl;
    }
};
complex ::complex(void)
{ // NAME OF OBJECT AND CLASS MUST BE SAME !!!!!
    a = 89;
    b = 77;
}
int main()
{
    complex c;
    c.printData();
    return 0;
}